  "▶ Try the prototype": "▶ 试用原型",
  "Every image is real, and every image leads to a person you can book. A Creator’s portfolio is the user’s inspiration — the feed is the bridge between them.": "每一张图都是真的，每一张图背后都有一个可以预约的人。Creator 的作品集就是用户的灵感来源，Feed 就是连接两者的桥。",
  "Next: the problem": "接下来：问题",
  "I love it.": "好喜欢这个。",
  "Who made it?": "是谁做的？",
  "Every search starts with a picture, not a service name.": "每一次寻找，都从一张图开始，而不是一个服务名称。",
  "How might a picture someone loves lead straight to the person who can make it real?": "如何让一张心动的图片，直接通向能把它做出来的人？",
  "“I love it, but I don’t know what it’s called.”": "“我觉得好看，但不知道它叫什么。”",
  "People have a picture, not a service name.": "用户手里只有图，没有专业名称。",
  "“Pinterest shows me looks, not who can do them.”": "“Pinterest 给我看造型，却不告诉我谁能做。”",
  "The maker may be abroad, unqualified or untraceable.": "作者可能在国外、不专业，或根本找不到。",
  "“I have to pick a salon before I see the work.”": "“我得先选店，才能看到作品。”",
  "Shops and stars come first; the person’s skill comes last.": "先看店铺和评分，最后才看到人的手艺。",
  "“Instagram gives me likes, not bookings.”": "“Instagram 给我点赞，不给我预约。”",
  "Real work, every day — but few new customers.": "每天发真实作品，却很少带来新客户。",
  "Where this stands": "项目现状",
  "Built from my product outlines, a whole-product interactive demo and a Glasgow logic and business review. Interviews and field testing come next; accounts, Creators, prices and distances in the demo are simulated.": "依据我的产品大纲、一个完整产品的交互 Demo，以及针对格拉斯哥市场的逻辑与商业模式复盘。访谈和实地测试是下一步；Demo 中的账号、Creator、价格和距离均为模拟。",
  "Browse real work, save what they like, find who made it, compare and book.": "浏览真实作品，收藏喜欢的，找到作者，比较后预约。",
  "Creator": "Creator / 服务提供者",
  "Hairstylists, barbers, nail and makeup artists. Their portfolio is their profile, and it follows them if they change salons.": "发型师、理发师、美甲师、化妆师。作品集就是他们的主页，换店也会跟着他们走。",
  "Pilot operator": "试点运营者",
  "Recruits the first local Creators, sets trust rules for original work and client consent.": "招募首批本地 Creator，制定原创作品与客户授权的信任规则。",
  "Next: how the system works": "接下来：系统如何运转",
