  "See what people want": "了解用户需求",
  "Portable identity": "口碑随人走",
  "The loop that makes it grow": "让平台成长的闭环",
  "Creator uploads real work": "Creator 上传真实作品",
  "Work appears in the feed": "作品进入 Feed",
