  "I am a Research-led Multidisciplinary Designer. I connect user research, problem framing, systems thinking and experience design with AI-assisted rapid prototyping, testing and iteration. My work translates complex ecological, cultural and social systems into visual, interactive and research-led experiences.": "我是一名研究驱动的跨领域设计师。我连接用户研究、问题定义、系统思维与体验设计，并借助 AI 辅助快速原型、测试与迭代推进设计。我的作品将复杂的生态、文化和社会系统转化为视觉、互动与研究驱动的体验。",
