  "3D Environments / AI Video / Motion / Creative Technology ↗": "3D 环境设计 / AI 视频 / 动态影像 / 创意技术 ↗",
  "Worlds in motion. Tools for creation. ↗": "构建视觉世界，拓展创作方式。 ↗",
  "Original 3D environments, cinematic sequences, AI video and digital experiences. My work combines modelling, materials, lighting and camera design with AI-assisted production and reusable creative tools. ↗": "从原创三维场景、动画镜头、AI 视频到数字体验，将建模、材质、灯光与镜头设计，连接 AI 辅助制作和可复用的创作工具。 ↗",
