  "Original 3D films and creative resources ↗": "原创三维影像与创作资源 ↗",
  "Creative Tools & Resources ↗": "创作工具与资源 ↗",
  "Scene construction, materials, atmospheric lighting and camera animation. ↗": "场景构建、材质设计、氛围灯光与镜头动画。 ↗",
  "Motion Transfer, look direction, shot continuity and finishing edits. ↗": "动作迁移、风格方向、镜头连续性与后期剪辑。 ↗",
  "AI-assisted Motion & Web Experiences ↗": "AI 辅助动态影像与网页体验 ↗",
  "Character animation, visual direction and interactive web prototyping. ↗": "角色动画、视觉方向与交互网页原型。 ↗",
  "Blender tools, production workflows and publicly available project files. ↗": "Blender 工具、制作工作流与公开工程资源。 ↗",
  "01 / 3D Environments & Cinematography ↗": "01 / 3D 环境与镜头设计 ↗",
  "Original worlds, built and animated in Blender. ↗": "在 Blender 中构建并演绎原创世界。 ↗",
  "Cyberpunk architecture, floating landscapes and spacecraft flight sequences. I use scene construction, material design, atmospheric lighting and camera movement to establish scale, depth and a distinct visual identity. ↗": "赛博朋克建筑、浮空景观与飞行器镜头。通过场景构建、材质设计、氛围灯光和镜头运动，塑造空间尺度、景深与鲜明的视觉特征。 ↗",
  "Lighting & materials ↗": "灯光与材质 ↗",
  "02 / AI Video Production ↗": "02 / AI 视频制作 ↗",
  "One live-action scene, re-directed as a character film. ↗": "同一场真人实拍，重新导演成角色短片。 ↗",
  "A new direction in my practice: using AI video generation as a production tool rather than a one-click effect. With Motion Transfer, the movement and camera work of a live-action poker B-roll guide a new character and visual style, while the original timing and props carry through. The work is in choosing shots, defining the look, judging each generation and editing the passes into one clean film. ↗": "这是我实践中的新方向：把 AI 视频生成当作制作工具，而不是一键特效。通过动作迁移（Motion Transfer），以一段真人扑克 B-roll 的动作和运镜为参考，替换人物与画面风格并重新生成，同时保留原片的节奏与道具。真正的工作在于挑选镜头、确定风格、判断每一次生成的质量，并把多段生成剪辑成一部干净完整的短片。 ↗",
  "Higgsfield Genjutsu ↗": "Higgsfield Genjutsu ↗",
  "Look development ↗": "风格设定 ↗",
  "Editing & clean-up ↗": "剪辑与修帧 ↗",
  "Motion and camera reference: ↗": "动作与运镜参考： ↗",
  "Peter Lindgren — A CINEMATIC POKER B ROLL ↗": "Peter Lindgren — A CINEMATIC POKER B ROLL ↗",
  "Watch in 1080p ↗": "观看 1080p 版本 ↗",
  "Production process ↗": "制作流程 ↗",
  "Select the source ↗": "选择素材 ↗",
  "A cinematic poker B-roll with strong close-ups, hand actions and controlled lighting, which give the model clear motion to follow. ↗": "选择特写丰富、手部动作清晰、灯光可控的电影感扑克 B-roll，为模型提供明确的运动参照。 ↗",
  "Define the look ↗": "确定风格 ↗",
  "A stylised character with Egyptian-inspired gold jewellery, set against a green table and purple-magenta shadows. ↗": "风格化角色、埃及元素金饰，搭配绿色牌桌与紫红色暗部光影。 ↗",
  "Generate in passes ↗": "分段生成 ↗",
  "Motion Transfer in Higgsfield Genjutsu, in two passes (25 s and 21 s). Each pass was tested at 420p first and only rendered at 1080p once it worked, to avoid wasted generations. ↗": "在 Higgsfield Genjutsu 中用动作迁移分两段生成（25 秒与 21 秒）。每段先用 420p 测试，满意后再输出 1080p，减少不必要的消耗。 ↗",
  "Edit & clean up ↗": "剪辑与修帧 ↗",
  "The passes are cut into one 46-second film, with flickering frames removed and a high-quality 1080p export. ↗": "将两段剪成一部 46 秒短片，删除闪烁帧，并以 1080p 高画质导出。 ↗",
  "03 / AI-assisted Motion & Web Experiences ↗": "03 / AI 辅助动态影像与网页体验 ↗",
  "From visual direction to a working experience. ↗": "从视觉方向到可体验的成果。 ↗",
  "Naturalis brings botanical imagery and editorial typography into an immersive web prototype. In the Hyper3D collaboration, the character is generated with Hyper3D’s 3D AI and then imported into Blender to make the film. Each project shows a different application of visual direction and rapid production. ↗": "Naturalis 将植物影像与编辑式排版融入沉浸式网页原型；Hyper3D 合作中，角色先用 Hyper3D 的 3D AI 生成，再导入 Blender 完成成片。两项作品分别呈现视觉方向在交互体验和动态制作中的应用。 ↗",
  "Web experience design ↗": "网页体验设计 ↗",
  "Visual direction ↗": "视觉方向 ↗",
  "04 / Creative Tools & Resources ↗": "04 / 创作工具与资源 ↗",
  "Creative work with a public audience. ↗": "让创作走向真实受众。 ↗",
  "I publish original films, Blender workflows and reusable project resources across Douyin, Bilibili, Xiaohongshu and my resource platform. This connects visual production with tutorial development, resource distribution and creator feedback. ↗": "通过抖音、Bilibili、小红书和个人资源平台发布原创影像、Blender 工作流与可复用工程，将视觉制作连接教程开发、资源分发和创作者反馈。 ↗",
