  "Service design · UX research · MDes graduation project ↗": "服务设计 · 用户研究 · 硕士毕业设计 ↗",
  "Field research into why Chinese international graduates in the UK struggle to use the support around them as they move from study to work, and a paper decision practice I tested in two rounds with students. ↗": "在英中国留学生从学习走向工作时，身边明明有支持，为什么还是用不上？这是一次实地研究，以及一套和同学们一起测试了两轮的纸质决策练习。 ↗",
  "Completed · exploratory research, not a launched service ↗": "已完成 · 探索性研究，非已上线服务 ↗",
  "Two sticky-note walls from the first round of prototype testing ↗": "第一轮原型测试留下的两面便利贴墙 ↗",
  "Round 1 testing: the same practice, used by one participant with guidance (left) and one mostly alone (right). ↗": "第一轮测试：同一套练习，一位参与者需要引导（左），另一位基本独立完成（右）。 ↗",
  "In 30 seconds ↗": "30 秒速读 ↗",
  "My role ↗": "我的角色 ↗",
  "Solo project: research, synthesis, prototype design and testing ↗": "独立完成：调研、分析、原型设计与测试 ↗",
  "What I did ↗": "我做了什么 ↗",
  "Collected 6 student stories, compared Chinese and UK job platforms, visited 2 public employment services myself, then tested a paper prototype in 2 rounds ↗": "收集 6 个学生故事，对比中英文求职平台，亲自走访 2 家公共就业服务机构，再做了两轮纸质原型测试 ↗",
  "What I found ↗": "我发现了什么 ↗",
  "Help exists, but students can’t easily reach or judge it, so paid agencies selling “certainty” fill the gap ↗": "帮助是有的，但学生很难找到入口、也很难判断该信谁，于是卖“确定性”的付费中介趁机填补了空白 ↗",
  "Result ↗": "结果 ↗",
  "Students turned a pile of pressures into one clear next step. Anxiety didn’t disappear, and I say so. ↗": "学生能把一堆压力收敛成一个清楚的下一步。焦虑并没有消失，我也如实写出来。 ↗",
