  "A Pinterest-like, image-led platform where every picture is real work by a real, local Creator. For users, it is a way to find a look and the person who can actually do it. For Creators, it is a living portfolio that turns their work into new customers. ↗": "一个像 Pinterest 一样由图片引导的平台，但每一张图都是真实 Creator 完成的真实作品。对用户，它帮你找到喜欢的造型，以及真正能做出来的人；对 Creator，它是一个能把作品变成新客户的个人作品集。 ↗",
  "Interactive prototype · field research planned ↗": "交互原型可体验 · 现场调研待开展 ↗",
  "My contribution ↗": "我的工作 ↗",
  "Product strategy, service and system design, information architecture, UI and AI-assisted prototyping of both the user and Creator sides ↗": "产品策略、服务与系统设计、信息架构、界面，以及用户端与 Creator 端的 AI 辅助原型 ↗",
  "Scope ↗": "范围 ↗",
  "User + Creator mobile journeys ↗": "用户 + Creator 双端移动体验 ↗",
