  "Explore every screen ↓ ↗": "查看全部界面 ↓ ↗",
  "Download case PDF ↓ ↗": "下载案例 PDF ↓ ↗",
  "LOOK — Beauty Marketplace — interactive prototype ↗": "LOOK 见己 · 美容服务平台 · 交互原型 ↗",
  "Live prototype · demo data only ↗": "可直接操作 · 仅为演示数据 ↗",
  "Use the prototype directly in the frame. Nothing you enter is real: accounts, prices and appointments are demo fixtures. ↗": "可以直接在框内操作原型。所有账号、价格与预约均为演示数据，不会产生真实操作。 ↗",
  "Open full screen ↗": "全屏打开 ↗",
  "Running from the local review environment. This prototype is not a live commercial service. ↗": "当前由本地审核环境运行。此原型并非已上线的商业服务。 ↗",
  "The interactive version is being prepared for public release. Until then, the screens and flows below show the real prototype. ↗": "交互版正在准备公开上线。在此之前，下方的真实界面与流程即为原型内容。 ↗",
  "Choose the Consumer role and a preset demo name. Open a look → Make It Real → nearby Creators → service and availability. Switch to the matching Creator from Profile to inspect the same request. No real phone number or payment is needed. ↗": "选择消费者身份与预设演示称呼。打开造型 → Make It Real → 附近 Creator → 服务与空档。在个人页切换到对应 Creator，可查看同一请求。无需真实手机号或支付。 ↗",
