  "Durations are uncertain ↗": "时长并不确定 ↗",
  "Hair length and colour change how long a service takes, so estimates can still overrun. ↗": "头发长度与染发会改变服务时长，估算仍可能超时。 ↗",
  "Two kinds of customer ↗": "两类顾客 ↗",
  "WeChat suits Chinese customers but not everyone else, and Google sign-in may not work inside WeChat. Launching on the web with Chinese and English pages serves both, at the cost of that sign-in friction. ↗": "微信适合中国顾客，却不适合所有人；而在微信里 Google 登录可能用不了。先以中英文网页上线能照顾两类顾客，代价是登录上的这点摩擦。 ↗",
