  "The problems on this page come from over a year as a regular customer: watching how the shop runs, and listening for the owner’s own words rather than asking her to list problems. What has not happened yet is the owner using the finished app while I watch. ↗": "这页上的问题，来自我做老顾客的一年多：观察店是怎么运转的，在闲聊里留意店主自己的原话，而不是让她列出问题。还没做的，是让店主本人在我面前使用最终版。 ↗",
  "Done · from the customer’s chair ↗": "已完成 · 在理发椅上 ↗",
  "Over a year of haircuts I watched how a request moved from a WeChat message to the paper diary, and what broke when plans changed. She would not have listed her problems if asked, so in everyday talk — in the shop and over meals — I noted the moments she put one into words, kept her exact phrases and grouped them into pain points. When I showed her the idea, she wanted to try it. ↗": "理发一年多，我看到一个预约怎样从微信消息走进纸质本，计划一变又在哪里断掉。直接问她，她未必说得出问题在哪；所以在店里和饭桌上的日常闲聊中，我留意她把问题说出口的那些时刻，记下原话，再归类成痛点。我把想法讲给她听，她很想试试。 ↗",
  "Next · teach her, then watch a real day ↗": "下一步 · 教她用，再看她过一天 ↗",
  "On site: set it up with her, photograph the shop, then watch her handle a booking, a change and a closure. Record completion, errors, time and help needed. ↗": "到店里：和她一起设置好，拍下店里的照片，再看她处理一次预约、一次改动和一次停业；记录完成情况、出错、耗时和需要的帮助。 ↗",
  "Validate the operating rules ↗": "验证实际经营规则 ↗",
  "Confirm service lengths, opening windows, same-day policy, buffers and preferred language with the owner. Demo fixtures are not final business rules. ↗": "与店主核实服务时长、可预约的时间范围、当天预约政策、预约之间的缓冲时间和语言偏好；演示配置不作为最终经营规则。 ↗",
  "What I learned from the chair, and what I still need to test with her. ↗": "我在理发椅上看到了什么，还要和她一起验证什么。 ↗",
  "The prototype on this page runs the same rules as the live site, in the browser, on sample data. Automatic reminders are not released yet. ↗": "本页原型和线上网站用的是同一套规则，在浏览器里用示例数据运行。自动提醒尚未发布。 ↗",
  "Now · live website: Chinese and English booking + owner admin, one shared database ↗": "现在 · 网站已上线：中英文预约 + 店主管理端，共用一个数据库 ↗",
  "Next · fix launch bugs and test on real phones and the WeChat in-app browser ↗": "下一步 · 修复上线问题，在真实手机和微信内置浏览器中测试 ↗",
